const fs = require('fs');
const path = require('path');

function crc32(buf) {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) {
      const mask = -(crc & 1);
      crc = (crc >>> 1) ^ (0xedb88320 & mask);
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function adler32(buf) {
  let a = 1;
  let b = 0;
  const MOD = 65521;
  for (let i = 0; i < buf.length; i++) {
    a = (a + buf[i]) % MOD;
    b = (b + a) % MOD;
  }
  return ((b << 16) | a) >>> 0;
}

function u32be(n) {
  const b = Buffer.alloc(4);
  b.writeUInt32BE(n >>> 0, 0);
  return b;
}

function chunk(type, data) {
  const t = Buffer.from(type, 'ascii');
  const len = u32be(data.length);
  const crc = u32be(crc32(Buffer.concat([t, data])));
  return Buffer.concat([len, t, data, crc]);
}

function makePng(width, height, rgbaFn) {
  const rowLen = width * 4;
  const raw = Buffer.alloc((rowLen + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[(rowLen + 1) * y] = 0; // filter
    for (let x = 0; x < width; x++) {
      const [r, g, b, a] = rgbaFn(x, y);
      const idx = (rowLen + 1) * y + 1 + x * 4;
      raw[idx] = r;
      raw[idx + 1] = g;
      raw[idx + 2] = b;
      raw[idx + 3] = a;
    }
  }

  // zlib stream with uncompressed DEFLATE blocks
  const blocks = [];
  const MAX = 65535;
  let offset = 0;
  while (offset < raw.length) {
    const remaining = raw.length - offset;
    const size = Math.min(MAX, remaining);
    const final = offset + size >= raw.length ? 1 : 0;
    const header = Buffer.alloc(5);
    header[0] = final; // BFINAL=final, BTYPE=00
    header.writeUInt16LE(size, 1);
    header.writeUInt16LE((~size) & 0xffff, 3);
    blocks.push(header);
    blocks.push(raw.subarray(offset, offset + size));
    offset += size;
  }

  const zlibHeader = Buffer.from([0x78, 0x01]); // no compression
  const ad = u32be(adler32(raw));
  const idat = Buffer.concat([zlibHeader, ...blocks, ad]);

  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // color type RGBA
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  return Buffer.concat([
    signature,
    chunk('IHDR', ihdr),
    chunk('IDAT', idat),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function gradient(w, h, c1, c2, noise = false) {
  return makePng(w, h, (x, y) => {
    const t = y / (h - 1);
    let r = Math.round(lerp(c1[0], c2[0], t));
    let g = Math.round(lerp(c1[1], c2[1], t));
    let b = Math.round(lerp(c1[2], c2[2], t));
    if (noise) {
      const n = ((x * 13 + y * 17) % 11) - 5;
      r = Math.max(0, Math.min(255, r + n));
      g = Math.max(0, Math.min(255, g + n));
      b = Math.max(0, Math.min(255, b + n));
    }
    return [r, g, b, 255];
  });
